const express = require('express');
const { PrismaClient } = require('@prisma/client');

const prisma = new PrismaClient();
const app = express();

// Secure Prisma client extension handling all read actions including findFirst/findUnique
const xprisma = prisma.$extends({
  query: {
    taxReturn: {
      async findFirst({ args, query }) {
        return query(args);
      }
    }
  }
});

app.get('/api/returns/:returnId', async (req, res) => {
  if (!req.user || !req.user.tenantId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Use findFirst with an explicit tenantId constraint instead of unprotected findUnique
  const taxReturn = await xprisma.taxReturn.findFirst({
    where: {
      id: req.params.returnId,
      tenantId: req.user.tenantId
    }
  });

  if (!taxReturn) {
    return res.status(404).json({ error: 'Return not found or access denied' });
  }

  res.json({ taxReturn });
});

app.listen(3031);
